#!/usr/bin/env node
// AUTO-GENERATED SYNC SCRIPT — copies canonical markdown from ../ko and ../en
// into src/content/docs/<locale>/... for the Starlight build.
// Do NOT hand-edit files under src/content/docs — edit the source in ../ko or ../en instead.
// This script only adds/normalizes Starlight frontmatter; it never touches prose.

import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync, existsSync, copyFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..", "..");
const SITE_ROOT = join(__dirname, "..");
const OUT_ROOT = join(SITE_ROOT, "src", "content", "docs");

const BASE = "/business-planning-handbook/";
const LOCALES = ["ko", "en"];

const CHAPTERS = ["CH01", "CH02", "CH03", "CH04", "CH05", "CH06", "CH07", "CH08"];

function readSource(locale, sub, file) {
  return readFileSync(join(REPO_ROOT, locale, sub, file), "utf8");
}

function listDirExt(locale, sub, ext) {
  const dir = join(REPO_ROOT, locale, sub);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith(ext)).sort();
}

function listDir(locale, sub) {
  const dir = join(REPO_ROOT, locale, sub);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
}

// Extract the first level-1 "# Title" heading as the page title, and strip it
// from the body (Starlight renders the frontmatter title as the H1 itself).
function extractTitle(md, fallback) {
  const m = md.match(/^#\s+(.+?)\s*$/m);
  if (!m) return { title: fallback, body: md };
  const title = m[1].trim();
  const body = md.slice(0, m.index) + md.slice(m.index + m[0].length);
  return { title, body: body.replace(/^\s+/, "") };
}

function yamlEscape(s) {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

function yamlLine(key, value, indent) {
  const pad = "  ".repeat(indent);
  if (value === undefined) return null;
  if (value !== null && typeof value === "object") {
    const nested = Object.entries(value)
      .map(([k, v]) => yamlLine(k, v, indent + 1))
      .filter(Boolean)
      .join("\n");
    return `${pad}${key}:\n${nested}`;
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return `${pad}${key}: ${value}`;
  }
  return `${pad}${key}: ${yamlEscape(String(value))}`;
}

function writeGenerated(outPath, frontmatter, body) {
  mkdirSync(dirname(outPath), { recursive: true });
  const fmLines = Object.entries(frontmatter)
    .map(([k, v]) => yamlLine(k, v, 0))
    .filter(Boolean)
    .join("\n");
  const header = `---\n${fmLines}\n---\n<!-- AUTO-GENERATED by scripts/sync-content.mjs — do not edit, edit source in ko/ or en/ instead -->\n\n`;
  writeFileSync(outPath, header + body, "utf8");
}

// Clean previous generated output (keep the directory itself, which may hold
// non-generated files like index pages for the locale roots we author here).
rmSync(join(SITE_ROOT, "public", "worksheets"), { recursive: true, force: true });
if (existsSync(OUT_ROOT)) {
  rmSync(OUT_ROOT, { recursive: true, force: true });
}
mkdirSync(OUT_ROOT, { recursive: true });

// Collect chapter titles per locale (reused for the generated landing pages).
const chapterTitlesByLocale = {};
const appendixLinksByLocale = {};

// Extract the first paragraph (or two) of prose following the H1 in a README,
// stopping at the next heading. Used to seed the locale landing page intro
// without hand-copying prose into this script.
function extractIntro(md, maxParagraphs = 1) {
  const { body } = extractTitle(md, "");
  const paragraphs = body
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter((p) => p && !p.startsWith("#") && !p.startsWith(">"));
  return paragraphs.slice(0, maxParagraphs).join("\n\n");
}

for (const locale of LOCALES) {
  // Chapters
  let order = 1;
  const titles = [];
  for (const ch of CHAPTERS) {
    const file = `${ch}.md`;
    const raw = readSource(locale, "chapters", file);
    const { title, body } = extractTitle(raw, ch);
    titles.push(title);
    const fm = { title, sidebar: { order: order++ } };
    if (ch === CHAPTERS[0]) fm.prev = false;
    if (ch === CHAPTERS[CHAPTERS.length - 1]) fm.next = false;
    writeGenerated(join(OUT_ROOT, locale, "chapters", `${ch}.md`), fm, body);
  }
  chapterTitlesByLocale[locale] = titles;

  // Worksheets: only the raw .md the Worksheet Writer reads (no doc pages, no sidebar list)
  for (const file of listDir(locale, "manual")) {
    const raw = readSource(locale, "manual", file);
    const ch = (file.match(/^(CH\d\d)(?=-worksheet\.md$)/) || [file])[0];
    mkdirSync(join(SITE_ROOT, "public", "worksheets", locale), { recursive: true });
    writeFileSync(join(SITE_ROOT, "public", "worksheets", locale, file), raw, "utf8");
  }

  // Diagrams (canonical SVGs live in ko/diagrams and en/diagrams)
  for (const file of listDirExt(locale, "diagrams", ".svg")) {
    mkdirSync(join(OUT_ROOT, locale, "diagrams"), { recursive: true });
    copyFileSync(join(REPO_ROOT, locale, "diagrams", file), join(OUT_ROOT, locale, "diagrams", file));
  }

  // Appendices (supplementary material; ko first, en follows)
  let aOrder = 1;
  appendixLinksByLocale[locale] = [];
  for (const file of listDir(locale, "appendix")) {
    const raw = readSource(locale, "appendix", file);
    const fallback = file.replace(/\.md$/, "");
    const { title, body } = extractTitle(raw, fallback);
    appendixLinksByLocale[locale].push({ title, slug: file.replace(/\.md$/, "").toLowerCase() });
    writeGenerated(
      join(OUT_ROOT, locale, "appendix", file),
      { title, sidebar: { order: aOrder++ } },
      body
    );
  }
}

// Locale landing pages (index) — intro paragraph pulled from the canonical
// ko/en README.md (source of truth), chapter link list generated from the
// same titles already extracted from each chapter's H1 above. No prose is
// hand-copied here.

const LANDING_STRINGS = {
  ko: {
    title: "Business Planning Handbook",
    pathLabel: "ko",
    heading: "8개 챕터 학습 경로",
    appendixHeading: "부록",
    appendixNote: "부록은 챕터를 보완하는 심화 자료입니다. 부록 E·F와 C·D 보강은 v0.2에서 추가되었고 아직 사람이 내용 검토를 마치지 않은 초안입니다.",
    startLabel: "CH01부터 시작하기",
    worksheetsNote:
      "실습 워크시트는 왼쪽 사이드바의 **워크시트 작성기**에서 질문에 직접 답하고 Markdown 파일로 저장할 수 있습니다. [워크시트 작성기 열기](" + BASE + "ko/worksheet/)",
  },
  en: {
    title: "Business Planning Handbook",
    pathLabel: "en",
    heading: "8-Chapter Learning Path",
    appendixHeading: "Appendices",
    appendixNote: "The appendices are supplementary material that deepens the chapters. Appendices E and F and the additions to C and D were added in v0.2 and have not yet been fully human-reviewed.",
    startLabel: "Start with CH01",
    worksheetsNote:
      "The practical worksheets are in the **Worksheet Writer** in the sidebar on the left: answer the questions there and save them as a Markdown file. [Open the Worksheet Writer](" + BASE + "en/worksheet/)",
  },
};

for (const locale of LOCALES) {
  const strings = LANDING_STRINGS[locale];
  const readmeRaw = readFileSync(join(REPO_ROOT, locale, "README.md"), "utf8");
  const intro = extractIntro(readmeRaw, 1);

  const chapterLinks = CHAPTERS.map((ch, i) => {
    const title = chapterTitlesByLocale[locale][i];
    const href = `${BASE}${strings.pathLabel}/chapters/${ch.toLowerCase()}/`;
    return `- [${title}](${href})`;
  }).join("\n");

  const appendixLinks = (appendixLinksByLocale[locale] || [])
    .map((a) => `- [${a.title}](${BASE}${strings.pathLabel}/appendix/${a.slug}/)`)
    .join("\n");
  const appendixSection = appendixLinks
    ? `\n\n## ${strings.appendixHeading}\n\n${appendixLinks}\n\n${strings.appendixNote}`
    : "";

  const startHref = `${BASE}${strings.pathLabel}/chapters/${CHAPTERS[0].toLowerCase()}/`;

  const body = `${intro}\n\n## ${strings.heading}\n\n${chapterLinks}\n\n${strings.worksheetsNote}${appendixSection}\n\n[${strings.startLabel} →](${startHref})\n`;

  writeGenerated(join(OUT_ROOT, locale, "index.md"), { title: strings.title }, body);
}

// Root landing page: bilingual choice, no internal/operational info.
writeGenerated(
  join(OUT_ROOT, "index.md"),
  { title: "Business Planning Handbook", template: "splash" },
  `Business Planning Handbook — v0.2.0\n\n8 Chapters · 8 Worksheets\n\n- [한국어](/business-planning-handbook/ko/)\n- [English](/business-planning-handbook/en/)\n`
);

console.log("[sync-content] Synced ko/en chapters, manual into src/content/docs/");
